import{_ as a,c as o,o as e,b0 as s}from"./chunks/framework.BWMBvyU7.js";const r="/programming-docs/assets/image-20220430092434203.BNfT73Ga.png",_=JSON.parse('{"title":"LV005-栈简介","description":null,"frontmatter":{"title":"LV005-栈简介","date":"2026-03-13T14:01:06.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/data-structure/stack/126d38c48b8a146f02d8c089","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2026-03-13T14:01:06.326Z","fulluuid":"f02d8c089fed43da8b2ad07a63c99eaa","useduuid":"f02d8c089"}},"headers":[],"relativePath":"sdoc/data-structure/stack/126d38c48b8a146f02d8c089.md","filePath":"sdoc/02-数据结构/10-栈/LV005-栈简介.md","lastUpdated":1773672539000}'),l={name:"sdoc/data-structure/stack/126d38c48b8a146f02d8c089.md"};function n(d,t,c,i,p,u){return e(),o("div",null,[...t[0]||(t[0]=[s('<h1 id="lv005-栈简介" tabindex="-1">LV005-栈简介 <a class="header-anchor" href="#lv005-栈简介" aria-label="Permalink to &quot;LV005-栈简介&quot;">​</a></h1><h2 id="一、栈的概念" tabindex="-1">一、栈的概念 <a class="header-anchor" href="#一、栈的概念" aria-label="Permalink to &quot;一、栈的概念&quot;">​</a></h2><p>栈是限制在一端进行插入操作和删除操作的 <strong>线性表</strong>（俗称 <strong>堆栈</strong>）。</p><ul><li><p><strong>栈顶</strong>：允许进行操作的一端称为栈顶。</p></li><li><p><strong>栈底</strong>：另一固定端称为栈底。</p></li><li><p><strong>空栈</strong>：没有元素的栈称为空栈。</p></li><li><p><strong>出栈</strong>：栈中提取出指定元素，此过程被称为出栈（或弹栈）。</p></li><li><p><strong>入栈</strong>：向栈中添加元素，此过程被称为进栈（入栈或压栈）。</p></li></ul><p>根据栈的定义，可以想象，水杯可以想象为一个栈，接水的时候相当于元素入栈，倒水的时候相当于元素出栈，没有水的时候就相当于空栈。</p><p>栈的特点是 <strong>后进先出</strong>（ LIFO ），它是一种特殊的线性存储结构，顺序结构和链式结构都可以实现栈，使用顺序结构实现的栈称为顺序栈，使用链式结构实现的栈称为链式栈。两种实现方式的区别仅限于数据元素在实际物理空间上存放的相对位置，顺序栈底层采用的是数组，链栈底层采用的是链表。</p><img src="'+r+'" alt="image-20220430092434203" style="zoom:33%;">',7)])])}const m=a(l,[["render",n]]);export{_ as __pageData,m as default};
